window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-12edd6fc36a72574"]={"versions": [{"id": "FIG-12edd6fc36a72574", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit konfigurierbarer Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein eigenes Längenfeld, bezeichnet mit „L_1“ bzw. „L_2“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ (für das erste Element) bzw. „E1,k_2“ (für das zweite Element).\n</li><li>Längenbemaßungen: Längenpfeil „n [byte]“ über die gesamte Struktur einschließlich des äußeren Längenfelds sowie individuelle Längenpfeile „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke (exklusive des jeweiligen inneren Längenfeldes).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Voranstellen des Gesamtlängenfeldes „Length n“.\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Zuerst das innere Längenfeld „L_1“, unmittelbar gefolgt von der geordneten Konkatenation der inneren Array-Elemente „E1,1“, „E1,2“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ im identischen Schema mit eigenem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung weiterer Dimensionen bzw. Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays müssen in Depth-First-Reihenfolge serialisiert werden.\n</li><li>Jedes Unter-Array (als SOME/IP-Array behandelt) erfordert ein eigenes, vorgelagertes Längenfeld („L_1“, „L_2“).\n</li><li>Die Bemaßung „L_1 [byte]“ bzw. „L_2 [byte]“ bemisst exakt die aggregierte Bytegröße der Nutzdatenelemente des jeweiligen Unter-Arrays, während „n [byte]“ die Gesamtlänge des Bytestroms ab dem äußeren Längenfeld angibt.\n</li><li>Die Bitbreite des Längenfeldes ist gemäß Manifest auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cba90f60da394486", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit konfigurierbarer Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein eigenes Längenfeld, bezeichnet mit „L_1“ bzw. „L_2“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ (für das erste Element) bzw. „E1,k_2“ (für das zweite Element).\n</li><li>Längenbemaßungen: Längenpfeil „n [byte]“ über die gesamte Struktur einschließlich des äußeren Längenfelds sowie individuelle Längenpfeile „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke (exklusive des jeweiligen inneren Längenfeldes).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Voranstellen des Gesamtlängenfeldes „Length n“.\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Zuerst das innere Längenfeld „L_1“, unmittelbar gefolgt von der geordneten Konkatenation der inneren Array-Elemente „E1,1“, „E1,2“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ im identischen Schema mit eigenem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung weiterer Dimensionen bzw. Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays müssen in Depth-First-Reihenfolge serialisiert werden.\n</li><li>Jedes Unter-Array (als SOME/IP-Array behandelt) erfordert ein eigenes, vorgelagertes Längenfeld („L_1“, „L_2“).\n</li><li>Die Bemaßung „L_1 [byte]“ bzw. „L_2 [byte]“ bemisst exakt die aggregierte Bytegröße der Nutzdatenelemente des jeweiligen Unter-Arrays, während „n [byte]“ die Gesamtlänge des Bytestroms ab dem äußeren Längenfeld angibt.\n</li><li>Die Bitbreite des Längenfeldes ist gemäß Manifest auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-49ffbb3e79489b08", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit konfigurierbarer Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein eigenes Längenfeld, bezeichnet mit „L_1“ bzw. „L_2“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ (für das erste Element) bzw. „E1,k_2“ (für das zweite Element).\n</li><li>Längenbemaßungen: Längenpfeil „n [byte]“ über die gesamte Struktur einschließlich des äußeren Längenfelds sowie individuelle Längenpfeile „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke (exklusive des jeweiligen inneren Längenfeldes).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Voranstellen des Gesamtlängenfeldes „Length n“.\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Zuerst das innere Längenfeld „L_1“, unmittelbar gefolgt von der geordneten Konkatenation der inneren Array-Elemente „E1,1“, „E1,2“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ im identischen Schema mit eigenem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung weiterer Dimensionen bzw. Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays müssen in Depth-First-Reihenfolge serialisiert werden.\n</li><li>Jedes Unter-Array (als SOME/IP-Array behandelt) erfordert ein eigenes, vorgelagertes Längenfeld („L_1“, „L_2“).\n</li><li>Die Bemaßung „L_1 [byte]“ bzw. „L_2 [byte]“ bemisst exakt die aggregierte Bytegröße der Nutzdatenelemente des jeweiligen Unter-Arrays, während „n [byte]“ die Gesamtlänge des Bytestroms ab dem äußeren Längenfeld angibt.\n</li><li>Die Bitbreite des Längenfeldes ist gemäß Manifest auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9963d8d5c8d9bd49", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit konfigurierbarer Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein eigenes Längenfeld, bezeichnet mit „L_1“ bzw. „L_2“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ (für das erste Element) bzw. „E1,k_2“ (für das zweite Element).\n</li><li>Längenbemaßungen: Längenpfeil „n [byte]“ über die gesamte Struktur einschließlich des äußeren Längenfelds sowie individuelle Längenpfeile „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke (exklusive des jeweiligen inneren Längenfeldes).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Voranstellen des Gesamtlängenfeldes „Length n“.\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Zuerst das innere Längenfeld „L_1“, unmittelbar gefolgt von der geordneten Konkatenation der inneren Array-Elemente „E1,1“, „E1,2“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ im identischen Schema mit eigenem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung weiterer Dimensionen bzw. Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays müssen in Depth-First-Reihenfolge serialisiert werden.\n</li><li>Jedes Unter-Array (als SOME/IP-Array behandelt) erfordert ein eigenes, vorgelagertes Längenfeld („L_1“, „L_2“).\n</li><li>Die Bemaßung „L_1 [byte]“ bzw. „L_2 [byte]“ bemisst exakt die aggregierte Bytegröße der Nutzdatenelemente des jeweiligen Unter-Arrays, während „n [byte]“ die Gesamtlänge des Bytestroms ab dem äußeren Längenfeld angibt.\n</li><li>Die Bitbreite des Längenfeldes ist gemäß Manifest auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-825716b811b39947", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit konfigurierbarer Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein eigenes Längenfeld, bezeichnet mit „L_1“ bzw. „L_2“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ (für das erste Element) bzw. „E1,k_2“ (für das zweite Element).\n</li><li>Längenbemaßungen: Längenpfeil „n [byte]“ über die gesamte Struktur einschließlich des äußeren Längenfelds sowie individuelle Längenpfeile „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke (exklusive des jeweiligen inneren Längenfeldes).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Voranstellen des Gesamtlängenfeldes „Length n“.\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Zuerst das innere Längenfeld „L_1“, unmittelbar gefolgt von der geordneten Konkatenation der inneren Array-Elemente „E1,1“, „E1,2“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ im identischen Schema mit eigenem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung weiterer Dimensionen bzw. Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays müssen in Depth-First-Reihenfolge serialisiert werden.\n</li><li>Jedes Unter-Array (als SOME/IP-Array behandelt) erfordert ein eigenes, vorgelagertes Längenfeld („L_1“, „L_2“).\n</li><li>Die Bemaßung „L_1 [byte]“ bzw. „L_2 [byte]“ bemisst exakt die aggregierte Bytegröße der Nutzdatenelemente des jeweiligen Unter-Arrays, während „n [byte]“ die Gesamtlänge des Bytestroms ab dem äußeren Längenfeld angibt.\n</li><li>Die Bitbreite des Längenfeldes ist gemäß Manifest auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-963fc0a4f68f9723", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit der Zusatzbezeichnung „LengthField (optional)“ und einer konfigurierbaren Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein Längenfeld „L_1“ bzw. „L_2“, jeweils annotiert mit „LengthField (optional)“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ bzw. „E1,k_2“.\n</li><li>Längenbemaßungen:\n<ul class=\"fig-list\"><li>Bemaßung „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke des jeweiligen inneren Arrays (exklusive des inneren Längenfeldes).\n</li><li>Bemaßung „n [byte]“ über die Gesamtheit der Array-Elemente ohne das äußere Längenfeld.\n</li><li>Gesamtlängenbemaßung „LengthField + n [byte]“ über das äußere Längenfeld und sämtliche Array-Elemente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Optionales Voranstellen des äußeren Längenfeldes („LengthField (optional)“ mit Länge n).\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Voranstellen des optionalen inneren Längenfeldes „L_1“, gefolgt von den Elementen „E1,1“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ mit optionalem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung der weiteren Array-Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays werden in Depth-First-Reihenfolge serialisiert.\n</li><li>Sowohl das äußere Längenfeld als auch die inneren Längenfelder („L_1“, „L_2“) sind optional konfigurierbar („LengthField (optional)“).\n</li><li>Bei vorhandenem äußerem Längenfeld gibt der Wert <code>n</code> die Byteanzahl der nachfolgenden Array-Elemente an; die gesamte Bytegröße des Konstrukts beträgt <code>LengthField + n [byte]</code>.\n</li><li>Die internen Bemaßungen „L_1 [byte]“ und „L_2 [byte]“ beziehen sich ausschließlich auf die Nutzdaten der Unter-Arrays.\n</li><li>Die Bitbreite von Längenfeldern ist auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6bf9d9a6d91d4381", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Serialisierungs- und Datenstrom-Layoutdiagramm im Kontext des AUTOSAR Adaptive Platform Communication Management (SOME/IP-Serialisierung). Das Schaubild stellt das lineare Byte-Layout bei der Serialisierung mehrdimensionaler Arrays (Multi-dimensional arrays) im Protokoll-Payload dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Datenstrukturen und Felder:</p>\n<ul class=\"fig-list\"><li>Äußeres Längenfeld: Box „Length n“ mit der Zusatzbezeichnung „LengthField (optional)“ und einer konfigurierbaren Breite von „8, 16 or 32 bit“.\n</li><li>Übergeordnete Array-Elemente: Sequenz von verschachtelten Elementen, beispielhaft dargestellt durch „Element_a[1][j…k_1]“ und „Element_a[2][j…k_2]“, gefolgt von Fortsetzungspunkten („…“).\n</li><li>Innere Längenfelder: Jedes Unter-Array besitzt ein Längenfeld „L_1“ bzw. „L_2“, jeweils annotiert mit „LengthField (optional)“.\n</li><li>Nutzdaten-Elemente der Unter-Arrays: Fortlaufende Elemente „E1,1“, „E1,2“ bis „E1,k_1“ bzw. „E1,k_2“.\n</li><li>Längenbemaßungen:\n<ul class=\"fig-list\"><li>Bemaßung „L_1 [byte]“ und „L_2 [byte]“ über die Nutzdatenblöcke des jeweiligen inneren Arrays (exklusive des inneren Längenfeldes).\n</li><li>Bemaßung „n [byte]“ über die Gesamtheit der Array-Elemente ohne das äußere Längenfeld.\n</li><li>Gesamtlängenbemaßung „LengthField + n [byte]“ über das äußere Längenfeld und sämtliche Array-Elemente.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Die Serialisierung erfolgt sequenziell in Tiefensuche (Depth-First-Order):</p>\n<ol class=\"fig-list\"><li>Optionales Voranstellen des äußeren Längenfeldes („LengthField (optional)“ mit Länge n).\n</li><li>Serialisierung des ersten übergeordneten Elements „Element_a[1]“: Voranstellen des optionalen inneren Längenfeldes „L_1“, gefolgt von den Elementen „E1,1“ bis „E1,k_1“.\n</li><li>Serialisierung nachfolgender übergeordneter Elemente wie „Element_a[2]“ mit optionalem Längenfeld „L_2“ und Elementen bis „E1,k_2“.\n</li><li>Fortsetzung der weiteren Array-Elemente entlang des Bytestroms.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgaben für SOME/IP-Serialisierer und Deserialisierer:</p>\n<ul class=\"fig-list\"><li>Mehrdimensionale Arrays werden in Depth-First-Reihenfolge serialisiert.\n</li><li>Sowohl das äußere Längenfeld als auch die inneren Längenfelder („L_1“, „L_2“) sind optional konfigurierbar („LengthField (optional)“).\n</li><li>Bei vorhandenem äußerem Längenfeld gibt der Wert <code>n</code> die Byteanzahl der nachfolgenden Array-Elemente an; die gesamte Bytegröße des Konstrukts beträgt <code>LengthField + n [byte]</code>.\n</li><li>Die internen Bemaßungen „L_1 [byte]“ und „L_2 [byte]“ beziehen sich ausschließlich auf die Nutzdaten der Unter-Arrays.\n</li><li>Die Bitbreite von Längenfeldern ist auf 8, 16 oder 32 Bit parametrierbar.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-12edd6fc36a72574", "to": "FIG-cba90f60da394486", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cba90f60da394486", "to": "FIG-49ffbb3e79489b08", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-49ffbb3e79489b08", "to": "FIG-cba90f60da394486", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cba90f60da394486", "to": "FIG-9963d8d5c8d9bd49", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9963d8d5c8d9bd49", "to": "FIG-825716b811b39947", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-825716b811b39947", "to": "FIG-963fc0a4f68f9723", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Äußeres Längenfeld: Kennzeichnung um den Textzusatz „LengthField (optional)“ ergänzt.\n</li><li>Innere Längenfelder (<code>L_1</code>, <code>L_2</code>): Jeweils um die Beschriftung „LengthField (optional)“ unterhalb des Bezeichners ergänzt.\n</li><li>Gesamtlängenbemaßung: Pfeilbereich für <code>n [byte]</code> beginnt erst nach dem äußeren Längenfeld (deckt nur die Payload der äußeren Array-Elemente ab).\n</li><li>Neue Gesamtlängenbemaßung: Maßpfeil <code>LengthField + n [byte]</code> unterhalb von <code>n [byte]</code> eingefügt, der das äußere Längenfeld und die Payload umfasst.\n</li><li>Rechter Rand: Auslassungspunkte <code>...</code> nach <code>L_2 [byte]</code> auf Elementebene entfernt.\n</li></ul>"}, {"from": "FIG-963fc0a4f68f9723", "to": "FIG-6bf9d9a6d91d4381", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
